INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (703914, 'Контекст', 'Дошкольное воспитание и обучение – первый уровень системы непрерывного образования. Общеобразовательные учебные программы  дошкольного воспитания и обучения данного уровня обеспечивают преемственность и непрерывность дошкольного и начального образования с учетом принципа единства воспитания и обучения, развития и оздоровления детей и предшествуют уровню начального образования.') ON CONFLICT DO NOTHING;
