INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (702612, 'Определение показателя', 'доходы от проведенных экскурсий - доходы полученные от показа объектов  под руководством квалифицированного специалиста  экскурсовода, который передает аудитории видение объекта, оценку памятного места, понимание исторического события, связанного с этим объектом.') ON CONFLICT DO NOTHING;
