INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (702920, 'Методика расчета', 'Численность работников списочного состава за вычетом отдельных категорий работников, имеющих формальное прикрепление к работе (лица, находящиеся в отпусках по беременности и родам, по уходу за ребенком и другие). Кроме того, в фактической численности расчетно учитываются: фактическое число работников, принятых по совместительству, либо принятых на неполный рабочий день или неполную рабочую неделю; надомные работники; лица, привлеченные для работы в организации по договорам гражданско-правового характера,заключенным с работодателями.') ON CONFLICT DO NOTHING;
