INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (4799287, 'Определение показателя', 'Прибыль или смешанный доход — это показатели, характеризующие получаемый в процессе производства результат (за вычетом издержек), до вычета любых платежей в явной или неявной форме процентов, ренты или других доходов от собственности, подлежащих выплате за использование финансовых активов, земли или других природных ресурсов, необходимых для осуществления производства. Термин "валовая" или "чистая" в данном случае указывает на то, включает или не включает этот показатель потребление основного капитала в процессе производства. (СНС 2008, п.7.12)') ON CONFLICT DO NOTHING;
