INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (701053, 'Определение показателя', 'Выпуск определяется как стоимость товаров и услуг, произведенных заведением, исключая стоимость любых товаров и услуг, использованных в деятельности, в отношении которых заведение не принимает риск, связанный с использованием продуктов в производстве, и исключая стоимость товаров и услуг, потребленных тем же самым заведением, за исключением товаров и услуг, использованных для накопления (основного капитала или запасов материальных оборотных средств) или для собственного конечного потребления. (СНС 2008, Глоссарий)') ON CONFLICT DO NOTHING;
