INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (703003, 'Определение показателя', 'В численность выбывших включаются все работники, оставившие работу в данной организации, независимо от оснований (расторжение трудового договора по инициативе работника или администрации, соглашение сторон, призыв или поступление на военную службу, перевод работника с его согласия в другую организацию и др.), уход или перевод которых оформлен приказом (распоряжением), а также выбывшие в связи со смертью.') ON CONFLICT DO NOTHING;
