INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (2709379, 'Комментарии', e'Сроки публикации. Оперативные данные на месячной основе - 17 февраля.  Предварительные данные: на квартальной основе - 21 апреля, за 1 квартал - 19 мая, за 1 полугодие - 18 августа, за 9 месяцев - 17 ноября. Отчетные данные: на годовой основе - 29 июля, за 1 квартал - 30 июня, за 1 полугодие - 29 сентября, за 9 месяцев  - 26 декабря.
