INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (2709379, 'Методика расчета', 'Валовой внутренний продукт методом производства получается путем суммирования валовой добавленной стоимости по отраслям. Валовой внутренний продукт рассчитывается по рыночным ценам, то есть включает в себя чистые налоги на продукты и на импорт. Термин «чистые» означает, что налоги показаны за вычетом соответствующих субсидий.Показатель рассчитывается в соответствии с методологией СНС93.') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (2709379, 'Ответственное лицо', 'Управление национальных счетов') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (2709379, 'Определение показателя', 'ВВП методом производства представляет собой конечный результат производственной деятельности производителей-резидентов и представялет собой сумму добавленной стоимости и чистых налогов на продукты и импорт.') ON CONFLICT DO NOTHING;
