INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (703157, 'Определение показателя', 'расходы, связанные с реализацией продукции и оказанием услуг. К ним относятся: заработная плата, отчисления от заработной платы работников отдела сбыта, расходы по страхованию собственности, командировочные расходы, амортизационные отчисления и расходы по содержанию объектов недвижимости, транспортировка грузов до пункта отправления, погрузочно-разгрузочные работы; расходы на маркетинговые услуги и другие аналогичные расходы') ON CONFLICT DO NOTHING;
