INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700945, 'Определение показателя', 'Прибыль представляет собой ту часть добавленной стоимости, которая остается у производителей после вычета расходов, связанных с оплатой труда наемных работников и уплатой налогов на производство. Термин "валовая" или "чистая" в данном случае указывает на то, включает или не включает этот показатель потребление основного капитала в процессе производства.') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700945, 'Методика расчета', 'Прибыль или смешанные доходы является балансирующей статьей в расчете ВВП методом доходов, то есть расчитывается вычитанием: ВВП минус оплата труда наемных работников минус налоги на производство и импорт плюс субсидии на производство и импорт. Термин «чистая»  или  «валовая» в данном случае указывает на то, включает или не включает этот показатель потребление основного капитала в процессе производства.') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700945, 'Комментарии', e'Сроки публикации:
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700945, 'История показателя', 'Имеется следующая динамика: годовые - с 1990г. (1990-1992гг - млн. рублей, с 1993г. - млн. тенге 1990-1997гг. - ОКОНХ, 1998-2009гг. - старый ОКЭД, с 2010г. - новый ОКЭД) квартальные - с 2008г. - старый ОКЭД, с 2010г. - новый ОКЭД.') ON CONFLICT DO NOTHING;
