INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (18805320, 'Определение показателя', 'число национальных полнометражных фильмов, созданных в видео-формате - количество полнометражных фильмов, созданных в видео-формате. Полнометражный фильм в видео-формате – это фильм продолжительностью 60 минут и более, созданный исключительно в видео-формате и не предназначенный для проката в кинотеатрах. Видео-формат включает в себя все форматы видео дисков (DVD, VCD), диски с высоким разрешением (HD DVD, Blu-Ray disc) и видео записи на пленке (VHS).') ON CONFLICT DO NOTHING;
