INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (702199, 'Определение показателя', 'В зависимости от оборудования вагоны, предназначенные для перевозки пассажиров, делятся на мягкие, мягкожесткие, жесткие, купейные, жесткие открытые, межобластные с местами для сидения. Вместимость пассажирского транспортного средства – число сидячих и спальных мест и разрешенное число мест для стоящих пассажиров в пассажирском транспортном средстве, когда оно используется по назначению') ON CONFLICT DO NOTHING;
