INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (19778396, 'Источники определения', 'Инструкция по заполнению статистической формы общегосударственного статистического наблюдения «Отчет об использовании ИКТ на предприятиях»') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (19778396, 'Определение показателя', 'Обеспечивает электронный обмен данными между партнерами по бизнесу посредством сообщений формата EDI. Деловая информация, которой обмениваются бизнес партнеры, включает заказы на покупку, счета-фактуры, транспортные уведомления и так далее. Применение EDI обеспечивает достоверность и конфиденциальность передаваемой информации, а также значительно упрощает размещение и прием заказов предприятиями. Кроме того, заказы, полученные через сообщения EDI формата, в международной практике входят в расчет электронной коммерции.') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (19778396, 'Источник показателя', '3-информ «Отчет об использовании информационно-коммуникационных технологий на предприятиях»') ON CONFLICT DO NOTHING;
