INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (2709435, 'Определение показателя', 'Валовой внутренний продукт, получаемый методом доходов, определяет структуру ВВП с точки зрения первичных доходов: оплаты труда наемных работников, налогов на производство и импорт, потребления основного капитала, прибыли/смешанного дохода . Валовой внутренний продукт методом доходов составляется на основании счета образования доходов.                                                                        ВВП методом доходов равен сумме вышеназванных первичных доходов, распределенных по производителям-резидентам.') ON CONFLICT DO NOTHING;
