INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (702193, 'Описание гармонизации', 'Индексы физического объема транспортных услуг, рассчитанные к предыдущим месяцам, гармонизируются с целью согласования их с индексами физического объема периодов. Для согласования индексов используется метод наименьших квадратов (МНК), основанный на сведении к наименьшему отклонению разницы скорректированной (гармонизированной) месячной серии и первоначальной серии при определенном ограничении') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (702193, 'Определение показателя', 'Индекс физического объема услуг транспорта - это  изменение количественных объемов грузов и пассажирских перевозок в отчетном периоде по сравнению с базисным и исчисляется на основе средневзвешанного темпа роста грузооборота и пассажирооборота') ON CONFLICT DO NOTHING;
