INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700943, 'Определение показателя', 'Валовая прибыль - представляет собой ту часть добавленной стоимости, которая остается у производителей после вычета расходов, связанных с оплатой труда наемных работников и уплатой налогов на производство. Термин "валовая" или "чистая" в данном случае указывает на то, включает или не включает этот показатель потребление основного капитала в процессе производства.') ON CONFLICT DO NOTHING;
