INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (3056094, 'Определение показателя', 'Под числом абонентов передачи только данных по мобильной широкополосной связи подразумевается количество контрактов на услуги мобильной широкополосной связи, которые обеспечивают возможность доступа в открытый Интернет через HTTP и в которые не включены услуги передачи данных, то есть контракты, которые обеспечивают мобильную широкополосную связь как самостоятельную услугу (контракты на мобильную широкополосную связь для карт данных, USB-модемов (аппаратных ключей) и планшетных компьютеров). Контракты на передачу только данных по мобильной широкополосной связи с конкретными текущими платежами по контракту включаются в этот показатель независимо от фактического использования.') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (3056094, 'Краткое наименование КСП', 'Число абонентов только передачи данных по мобильной широкополосной связи') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (3056094, 'История показателя', 'Показатель "Число абонентов беспроводного широкополосного доступа в Интернет с использованием специализированных линий подвижной связи для передачи данных" формировался c 2012 года, с 2015 года был переименован на "Число абонентов беспроводного широкополосного доступа в Интернет с использованием специализированной подвижной связи для передачи данных", а с 2016 года переименован на "Число абонентов только передачи данных по мобильной широкополосной связи"') ON CONFLICT DO NOTHING;
