INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (18805319, 'Определение показателя', 'Прокатка таратылған фильмдердің саны - количество запущенных в прокат фильмов кинопрокатной организацией. Кинопрокатной организацией является коммерческое предприятие, занимающееся продажей, арендой, сдачей на прокат или обменом полнометражных фильмов с кинотетрами. Эти компании могут заниматься маркетингом и продвижением на рынок полнометражных фильмов, сбором выручки и их прокатом. ') ON CONFLICT DO NOTHING;
