INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (702216, 'Определение показателя', e'Оборот рабочего вагона – это время полного производственного цикла его работы – от одной погрузки до следующей погрузки. Этот цикл включает в себя время в движении по перегонам, простой на промежуточных станциях, время нахождения под грузовыми операциями и на технических станциях. Среднее время оборота грузового вагона по сети железных дорог определяется отношением затрат времени всего рабочего парка (в вагоно-сутках) к числу погруженных вагонов
