INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700963, 'Определение показателя', 'Скорректированный располагаемый доход является балансирующей статьей по счету перераспределения доходов в натуральной форме. Он выводится из располагаемого дохода институциональной единицы или сектора путем: а) прибавления суммы социальных трансфертов в натуральной форме, получаемых данной единицей или сектором; и б) вычитания суммы социальных трансфертов в натуральной форме, выплачиваемых данной единицей или сектором.') ON CONFLICT DO NOTHING;
