INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700942, 'Определение показателя', 'Условно-исчисленные отчисления работодателей на социальное страхование - это социальные пособия предоставляемые напрямую своим работникам, бывшим работникам или  их иждивенцам из собственных средств, не прибегая к услугам  страховых компаний или автономных пенсионных фондов и не создавая для этой цели специального фонда или отдельных резервов. ') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700942, 'История показателя', 'Имеется следующая динамика: годовые - с 1990г. (1990-1992гг - млн. рублей, с 1993г. - млн. тенге 1990-1997гг. - ОКОНХ, 1998-2009гг. - старый ОКЭД, с 2010г. - новый ОКЭД) квартальные - с 2008г. - старый ОКЭД, с 2010г. - новый ОКЭД.') ON CONFLICT DO NOTHING;
