INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (3056093, 'Определение показателя', 'Под числом абонентов передачи данных и речи по мобильной широкополосной связи подразумевается количество контрактов на услуги мобильной широкополосной связи, которые обеспечивают возможность доступа в открытый Интернет через HTTP и в которых услуги передачи данных включены в контракт вместе с услугами передачи речи (тарифные планы передачи речи и данных по сотовой связи) или как дополнительный пакет к тарифному плану передачи речи. Это контракты на основе смартфонов с услугами передачи речи и данных в том же терминале.') ON CONFLICT DO NOTHING;
