INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (3056093, 'История показателя', 'Показатель "Число абонентов беспроводного широкополосного доступа в Интернет с использованием стандартных линий подвижной связи и передачи данных на широкополосных скоростях" формировался c 2012 года, с 2015 года был переименован на "Число абонентов беспроводного широкополосного доступа в Интернет с использованием стандартной подвижной связи и передачи данных на широкополосных скоростях", а с 2016 года переименован на "Число абонентов по передаче данных и речи по мобильной широкополосной связи"') ON CONFLICT DO NOTHING;
