INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (18198759, 'Определение показателя', 'Субсидии – текущие некомпенсируемые выплаты из государственного бюджета предприятиям при условии производства ими определенного вида товаров и услуг. Субсидии на продукты и импорт - это субсидии, выплачиваемые обычно за единицу произведенного товара или услуги, то есть пропорционально количеству или стоимости товаров и услуг, производимых, продаваемых или импортируемых предприятиями-резидентами.') ON CONFLICT DO NOTHING;
