INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700958, 'Определение показателя', 'Текущие трансферты, переданные "остальному миру" - это текущие трансферты переданные нерезидентам. Трансферт представляет собой операцию, когда одна институциональная единица предоставляет товар, услугу или актив (финансовый или нефинансовый) другой единице, не получая взамен от нее возмещения в виде товара, услуги или актива. ') ON CONFLICT DO NOTHING;
