INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (702210, 'Определение показателя', 'Протяженность эксплуатируемых линий определяется расстоянием, измеряемым по оси пути от откидного бруса или знака «граница подъездного пути» до конечного пункта железнодорожных путей, независимо от того, является ли сам протяженный путь самостоятельным или это расстояние включает в себя несколько путей, не имеющих выхода на сеть железных дорог общего пользования. Протяженность эксплуатируемых линий определяется по оси путей между конечными пунктами объектов предприятия') ON CONFLICT DO NOTHING;
