INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700903, 'Наименование статистического показателя', 'Расходы на конечное потребление в счете товаров и услуг') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700903, 'Определение показателя', e'Расходы на конечное потребление представляют собой расходы на использование товаров и услуг для удовлетворения индивидуальных потребностей населения и коллективных потребностей общества в целом. Расходы на конечное потребление состоят из: а) расходов на конечное потребление домашних хозяйств; б) расходов государственных учреждений на индивидуальные товары и услуги и на коллективные услуги; в) расходов некоммерческих организаций, обслуживающих домашние хозяйства (НКООДХ). 
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700903, 'Код', '111105') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700903, 'Методика расчета', 'Расходы на конечное потребление состоят из расходов на конечное потребление домашних хозяйств, расходов органов государственного управления на покупку потребительских товаров и услуг у рыночных производителей для передачи домашним хозяйствам, расходов некоммерческих организаций, обслуживающих домашние хозяйства (НКООДХ). Показатель рассчитывается в соответствии с методологией СНС93.') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700903, 'Комментарии', e'Сроки публикации: Предварительные данные: на квартальной основе - 27 апреля Отчетные данные: на годовой основе - 17 ноября, за 1 квартал - 14 июля, за 1 полугодие - 13 октября, за 9 месяцев - 29 декабря 
