INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700938, 'История показателя', 'Имеется следующая динамика: годовые - с 1990г. (1990-1992гг - млн. рублей, с 1993г. - млн. тенге 1990-1997гг. - ОКОНХ, 1998-2009гг. - старый ОКЭД, с 2010г. - новый ОКЭД) квартальные - с 2008г. - старый ОКЭД, с 2010г. - новый ОКЭД.') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700938, 'Определение показателя', 'Оплата труда наемных работников - это вознаграждение в денежной или натуральной форме, которое должно быть выплачено работодателем наемному работнику за работу, выполненную в отчетном периоде.') ON CONFLICT DO NOTHING;
