INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700938, 'Методика расчета', 'Оплата труда работников определяется суммой всех вознаграждений в денежной и/или натуральной форме, выплачиваемых работодателями работникам за работу, выполненную ими в течение отчетного периода. Оплата труда работников учитывается на основе начисленных сумм и включает в себя суммы отчислений на социальное страхование.') ON CONFLICT DO NOTHING;
