INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (3056092, 'Определение показателя', e'Активное абонентское обслуживание по мобильной широкополосной связи относится к сумме активного абонентского обслуживания по обеспечению мобильного широкополосного доступа к сети Интернет на основе мобильного телефона и компьютера (USB (электронные ключи). Включает только фактических, а не потенциальных абонентов, хотя последние имеют возможность использовать телефоны с поддержкой широкополосной связи. Абонентское обслуживание включает в себя регулярную абонентскую плату или требование использования пользователи имеют доступ к сети Интернет в течение последних 3 месяцев. Включает в себя абонентское обслуживание по мобильным широкополосным сетям, обеспечивающих скорсть загрузки не менее 256 кбит/с (WCDMA, HSDPA, CDMA 2000 1xEV-DO, WiMах стандарта IEEE 802.16e и LTE). 
