INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (700966, 'Определение показателя', 'Расходы на конечное потребление домашних хозяйств включают расходы домашних хозяйств на приобретение потребительских товаров и услуг во всех торговых предприятиях, на городских рынках и через неорганизованную (уличную) торговлю, предприятиях бытового обслуживания, пассажирского транспорта, связи, гостиницах, платных учреждениях культуры, здравоохранения, образования, а также потребление товаров и услуг в натуральной форме, произведенных для себя (сельскохозяйственная продукция личных подсобных хозяйств, условно исчисленные услуги по проживанию в собственном жилище) и полученных в качестве оплаты труда.') ON CONFLICT DO NOTHING;
