INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (3026906, 'Определение показателя', 'Показывается поступление каждого вида топлива и энергии от предприятий своей области и других областей и из импорта. Поступление по импорту показывается в балансе оптовых организаций, непосредственно получающих топливо из импорта для последующей поставки потребителям') ON CONFLICT DO NOTHING;
