INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (704492, 'Определение показателя', 'Минимальный денежный доход на одного человека, равный по величине стоимости минимальной потребительской корзины. Минимальная потребительская корзина представляет собой минимальный набор продуктов питания, товаров и услуг, необходимых для обеспечения жизнедеятельности человека, в натуральном и стоимостном выражении. Она состоит из продовольственной корзины и расходов на непродовольственные товары и платные услуги. Доля расходов на минимально необходимые непродовольственные товары и услуги для расчета прожиточного минимума установлена в размере 45 процентов стоимости минимальной потребительской корзины.') ON CONFLICT DO NOTHING;
INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (704492, 'Краткое наименование КСП', 'Прожиточный минимум; ВПМ; Стоимость минимальной потребительской корзины') ON CONFLICT DO NOTHING;
