INSERT INTO public.stat_info_passport (stat_id, title, value) VALUES (701960, 'Определение показателя', 'Арендные (коммунальные) жилые дома – дома, построенные в рамках Государственной программы жилищного строительства для сдачи в аренду социально-защищаемым слоям населения. Арендные (коммерческие) жилые дома – дома, построенные негосударственными застройщиками за счет частных инвестиций для сдачи в аренду государству. Жилые дома, построенные за счет кредитования местных исполнительных органов – дома, строительство которых велось в рамках Государственной программы жилищного строительства за счет кредитования местных исполнительных органов из республиканского бюджета. ') ON CONFLICT DO NOTHING;
